<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import type { ColDef } from 'ag-grid-community'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import AppDataGrid from '@/components/AppDataGrid.vue'
import KubernetesLabelDialog from '@/components/KubernetesLabelDialog.vue'
import KubernetesYamlEditor from '@/components/KubernetesYamlEditor.vue'
import KubernetesWorkloadEditor from '@/components/KubernetesWorkloadEditor.vue'
import KubernetesServiceEditor from '@/components/KubernetesServiceEditor.vue'
import { applyKubernetesObject, deleteKubernetesObject, getKubernetesObject, getKubernetesResourceTemplate, getKubernetesWorkloadStats, listKubernetesClusters, listKubernetesNamespaces, listKubernetesObjects, updateKubernetesObjectLabels, type KubernetesCluster, type KubernetesNamespace, type KubernetesObject } from '@/api/kubernetes'

type Option = { key: string; label: string; namespaced: boolean }
const groups: Record<string, { label: string; resources: Option[] }> = {
  network: { label: '网络管理', resources: [['services','Service'],['ingresses','Ingress'],['endpoints','Endpoints'],['networkpolicies','NetworkPolicy']].map(([key,label])=>({key,label,namespaced:true})) },
  config: { label: '配置管理', resources: [['configmaps','ConfigMap'],['secrets','Secret'],['resourcequotas','ResourceQuota'],['limitranges','LimitRange'],['horizontalpodautoscalers','HPA'],['poddisruptionbudgets','PDB']].map(([key,label])=>({key,label,namespaced:true})) },
  storage: { label: '存储管理', resources: [{key:'persistentvolumeclaims',label:'PVC',namespaced:true},{key:'persistentvolumes',label:'PV',namespaced:false},{key:'storageclasses',label:'StorageClass',namespaced:false}] },
  access: { label: '访问控制', resources: [{key:'serviceaccounts',label:'ServiceAccount',namespaced:true},{key:'roles',label:'Role',namespaced:true},{key:'rolebindings',label:'RoleBinding',namespaced:true},{key:'clusterroles',label:'ClusterRole',namespaced:false},{key:'clusterrolebindings',label:'ClusterRoleBinding',namespaced:false}] },
  workloads: { label: '工作负载管理', resources: [['deployments','Deployment'],['statefulsets','StatefulSet'],['daemonsets','DaemonSet'],['jobs','Job'],['cronjobs','CronJob'],['pods','Pod']].map(([key,label])=>({key,label,namespaced:true})) },
  namespaces: { label: '命名空间', resources: [{key:'namespaces',label:'Namespace',namespaced:false}] },
}
const route=useRoute(), group=computed(()=>groups[String(route.meta.kubernetesGroup)]||groups.network), isWorkload=computed(()=>String(route.meta.kubernetesGroup)==='workloads'), isNetwork=computed(()=>String(route.meta.kubernetesGroup)==='network')
const clusters=ref<KubernetesCluster[]>([]), namespaces=ref<KubernetesNamespace[]>([]), clusterID=ref(0), resource=ref(''), namespace=ref(''), keyword=ref(''), rows=ref<KubernetesObject[]>([]), selected=ref<KubernetesObject[]>([])
const refreshing=ref(false)
const yamlDialog=ref(false),yaml=ref('')
const yamlResource=ref<KubernetesObject|null>(null),yamlReloading=ref(false)
const workloadEditorDialog=ref(false),workloadEditorYaml=ref(''),workloadEditorSaving=ref(false),workloadEditorCreate=ref(false)
const serviceEditorDialog=ref(false),serviceEditorYaml=ref(''),serviceEditorSaving=ref(false),serviceEditorCreate=ref(false)
const labelDialog=ref(false), labelSaving=ref(false), selectedLabelResource=ref<KubernetesObject|null>(null)
const workloadStats=ref({deployment:0,statefulSet:0,daemonSet:0,job:0,cronJob:0,pod:0})
const networkStats=ref<Record<string,number>>({services:0,ingresses:0,networkpolicies:0,endpoints:0})
const serviceType=ref('')
const current=computed(()=>group.value.resources.find(x=>x.key===resource.value)||group.value.resources[0])
const stats=computed(()=>[
  {key:'deployments',label:'Deployment',count:workloadStats.value.deployment,tone:'blue'}, {key:'pods',label:'Pod',count:workloadStats.value.pod,tone:'green'},
  {key:'statefulsets',label:'StatefulSet',count:workloadStats.value.statefulSet,tone:'purple'}, {key:'daemonsets',label:'DaemonSet',count:workloadStats.value.daemonSet,tone:'cyan'},
  {key:'jobs',label:'Job',count:workloadStats.value.job,tone:'orange'}, {key:'cronjobs',label:'CronJob',count:workloadStats.value.cronJob,tone:'pink'},
])
const networkCards=computed(()=>[
  {key:'services',label:'Services',count:networkStats.value.services},
  {key:'ingresses',label:'Ingress',count:networkStats.value.ingresses},
  {key:'networkpolicies',label:'Network Policies',count:networkStats.value.networkpolicies},
  {key:'endpoints',label:'Endpoints',count:networkStats.value.endpoints},
])
const displayedRows=computed(()=>resource.value==='services'&&serviceType.value?rows.value.filter(row=>row.service_type===serviceType.value):rows.value)
async function loadClusters(){const {data}=await listKubernetesClusters();clusters.value=data.data;const id=Number(route.query.cluster_id||0);clusterID.value=id&&clusters.value.some(x=>x.id===id)?id:(clusters.value[0]?.id||0)}
async function loadNamespaces(){if(!clusterID.value||(!isWorkload.value&&!isNetwork.value))return;const {data}=await listKubernetesNamespaces(clusterID.value);namespaces.value=data.data}
async function loadNetworkStats(){if(!isNetwork.value||!clusterID.value)return;const values=await Promise.all(group.value.resources.map(item=>listKubernetesObjects({cluster_id:clusterID.value,resource:item.key,namespace:namespace.value})));networkStats.value=Object.fromEntries(group.value.resources.map((item,index)=>[item.key,values[index].data.data.length]))}
async function load(){if(!clusterID.value){rows.value=[];return}const [list,summary]=await Promise.all([listKubernetesObjects({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,keyword:keyword.value}),isWorkload.value?getKubernetesWorkloadStats(clusterID.value,namespace.value):Promise.resolve(null),loadNetworkStats()]);rows.value=list.data.data;if(summary){const x=summary.data.data;workloadStats.value={deployment:x.deployment,statefulSet:x.stateful_set,daemonSet:x.daemon_set,job:x.job,cronJob:x.cron_job,pod:x.pod}}}
async function refresh(){refreshing.value=true;try{await Promise.all([loadNamespaces(),load()]);ElMessage.success('刷新成功')}finally{refreshing.value=false}}
function resourceRenderer(p:any){const row=p.data as KubernetesObject,wrap=document.createElement('div');wrap.className='resource-values';if(!row.requests?.cpu&&!row.requests?.memory&&!row.limits?.cpu&&!row.limits?.memory){wrap.textContent='-';return wrap}const add=(label:string,request?:string,limit?:string)=>{const line=document.createElement('div');line.className='resource-line';line.innerHTML=`<span class="resource-label">${label}:</span><code>${request||'-'}</code><i>/</i><code>${limit||'-'}</code>`;wrap.append(line)};add('CPU',row.requests?.cpu,row.limits?.cpu);add('Mem',row.requests?.memory,row.limits?.memory);return wrap}
function nameRenderer(p:any){const e=document.createElement('div');e.className='workload-name-cell';e.innerHTML=`<span><b>${p.value}</b><small>${p.data.namespace||'-'}</small></span>`;return e}
function labelRenderer(p:any){const labels=p.value||{},wrap=document.createElement('span'),icon=document.createElement('span'),badge=document.createElement('span');wrap.className='namespace-label-count';icon.className='namespace-label-icon';icon.textContent='◇';badge.className='namespace-label-badge';badge.textContent=String(Object.keys(labels).length);wrap.title='查看资源标签';wrap.onclick=()=>{selectedLabelResource.value=p.data;labelDialog.value=true};wrap.append(icon,badge);return wrap}
function shortImage(image:string){return image.split('/').pop()||image}
function imageRenderer(p:any){const images=(p.value||[]) as string[],wrap=document.createElement('div');wrap.className='workload-images';if(!images.length){wrap.textContent='-';return wrap}images.forEach(image=>{const tag=document.createElement('span');tag.className='workload-image';tag.textContent=shortImage(image);tag.onclick=async(event)=>{event.stopPropagation();await navigator.clipboard.writeText(image);ElMessage.success('完整镜像地址已复制')};wrap.append(tag)});return wrap}
function actionIcon(label:string,icon:string,action:()=>void,danger=false){const button=document.createElement('button');button.className=`icon-action${danger?' danger':''}`;button.title=label;button.setAttribute('aria-label',label);button.innerHTML=icon;button.onclick=action;return button}
function actionRenderer(p:any){const row=p.data as KubernetesObject,w=document.createElement('div');w.className='actions';const yamlIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/></svg>',editIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 20 4.2-1 10.6-10.6a2 2 0 0 0-2.8-2.8L5.4 16.2zM14.6 7l2.8 2.8M4 20h6"/></svg>',deleteIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14M10 11v6M14 11v6"/></svg>';w.append(actionIcon('YAML 编辑',yamlIcon,()=>editYAML(row)));if(isWorkload.value)w.append(actionIcon('编辑',editIcon,()=>{void editWorkload(row)}));else if(isNetwork.value&&resource.value==='services')w.append(actionIcon('编辑',editIcon,()=>{void editService(row)}));w.append(actionIcon('删除',deleteIcon,()=>remove(row),true));return w}
const base=()=>[{headerName:'序号',valueGetter:(p:any)=>p.node.rowIndex+1,width:62},{field:'name',headerName:'名称',cellRenderer:nameRenderer},{field:'labels',headerName:'标签',minWidth:100,cellRenderer:labelRenderer}] as ColDef[]
const imageColumn=(minWidth:number):ColDef=>({field:'images',headerName:'镜像',minWidth,cellRenderer:imageRenderer,tooltipValueGetter:p=>((p.value||[]) as string[]).join('\n')})
const columns=computed<ColDef[]>(()=>{const c=base();if(isNetwork.value){if(resource.value==='services')c.push({field:'service_type',headerName:'类型'},{field:'cluster_ip',headerName:'Cluster IP'},{field:'external_ip',headerName:'外部 IP',valueFormatter:p=>p.value||'-'},{field:'ports',headerName:'端口',valueFormatter:p=>(p.value||[]).join('\n')||'-'},{field:'endpoint_count',headerName:'端点'});else if(resource.value==='ingresses')c.push({field:'hosts',headerName:'主机',valueFormatter:p=>(p.value||[]).join(', ')||'-'},{field:'addresses',headerName:'地址',valueFormatter:p=>(p.value||[]).join(', ')||'-'});else if(resource.value==='endpoints')c.push({field:'addresses',headerName:'地址',valueFormatter:p=>(p.value||[]).join(', ')||'-'},{field:'ports',headerName:'端口',valueFormatter:p=>(p.value||[]).join(', ')||'-'},{field:'endpoint_count',headerName:'端点'});else c.push({field:'policy_types',headerName:'策略类型',valueFormatter:p=>(p.value||[]).join(', ')||'-'});c.push({field:'age',headerName:'存活时间'})}else if(!isWorkload.value)c.push({field:'kind',headerName:'类型'},{field:'status',headerName:'状态'},{field:'age',headerName:'存活时间'});else if(['deployments','statefulsets'].includes(resource.value))c.push({field:'ready',headerName:'容器组'},{headerName:'Requests / Limits',cellRenderer:resourceRenderer},imageColumn(160));else if(resource.value==='daemonsets')c.push({field:'ready',headerName:'准备就绪'},imageColumn(180));else if(resource.value==='jobs')c.push({field:'ready',headerName:'完成'},{field:'status',headerName:'状态'},imageColumn(160));else if(resource.value==='cronjobs')c.push({field:'schedule',headerName:'调度规则'},{field:'last_schedule_time',headerName:'最后调度',minWidth:170},{field:'suspended',headerName:'暂停',valueFormatter:p=>p.value?'是':'否'});else c.push({field:'ready',headerName:'就绪'},{field:'status',headerName:'状态'},{field:'restarts',headerName:'重启次数'},{field:'pod_ip',headerName:'Pod IP'},{field:'node',headerName:'调度节点',minWidth:150});if(isWorkload.value)c.push({field:'age',headerName:'存活时间'});c.push({headerName:'操作',pinned:'right',width:150,cellRenderer:actionRenderer});return c.map(column=>{const centered=column.headerName==='操作'||column.field==='labels';return {...column,headerClass:centered?'centered-grid-header':'left-grid-header',cellClass:centered?'centered-grid-cell':'left-grid-cell'}})})
async function blankYAML(){yamlResource.value=null;const {data}=await getKubernetesResourceTemplate({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value});yaml.value=data.data.yaml;yamlDialog.value=true}
async function editYAML(row:KubernetesObject){yamlResource.value=row;const {data}=await getKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name});yaml.value=data.data.yaml;yamlDialog.value=true}
async function reloadYAML(){yamlReloading.value=true;try{if(yamlResource.value){const row=yamlResource.value;const {data}=await getKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name});yaml.value=data.data.yaml}else{const {data}=await getKubernetesResourceTemplate({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value});yaml.value=data.data.yaml}ElMessage.success('已重新拉取最新 YAML')}finally{yamlReloading.value=false}}
async function editWorkload(row:KubernetesObject){const {data}=await getKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name});workloadEditorYaml.value=data.data.yaml;workloadEditorCreate.value=false;workloadEditorDialog.value=true}
async function openWorkloadCreate(){const {data}=await getKubernetesResourceTemplate({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value});workloadEditorYaml.value=data.data.yaml;workloadEditorCreate.value=true;workloadEditorDialog.value=true}
async function saveWorkloadEdit(value:string){workloadEditorSaving.value=true;try{await applyKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,yaml:value});workloadEditorDialog.value=false;ElMessage.success(workloadEditorCreate.value?'工作负载创建成功':'工作负载保存成功');await load()}finally{workloadEditorSaving.value=false}}
async function openServiceCreate(){const {data}=await getKubernetesResourceTemplate({cluster_id:clusterID.value,resource:'services',namespace:namespace.value});serviceEditorYaml.value=data.data.yaml;serviceEditorCreate.value=true;serviceEditorDialog.value=true}
async function editService(row:KubernetesObject){const {data}=await getKubernetesObject({cluster_id:clusterID.value,resource:'services',namespace:row.namespace,name:row.name});serviceEditorYaml.value=data.data.yaml;serviceEditorCreate.value=false;serviceEditorDialog.value=true}
async function saveService(value:string){serviceEditorSaving.value=true;try{await applyKubernetesObject({cluster_id:clusterID.value,resource:'services',namespace:namespace.value,yaml:value});serviceEditorDialog.value=false;ElMessage.success(serviceEditorCreate.value?'服务创建成功':'服务保存成功');await load()}finally{serviceEditorSaving.value=false}}
async function saveYAML(){await applyKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:namespace.value,yaml:yaml.value});yamlDialog.value=false;ElMessage.success('保存成功');await load()}
const deleteOne=(row:KubernetesObject)=>deleteKubernetesObject({cluster_id:clusterID.value,resource:resource.value,namespace:row.namespace,name:row.name})
async function remove(row:KubernetesObject){await ElMessageBox.confirm(`确定删除 ${row.name}？`,'确认删除');await deleteOne(row);ElMessage.success('删除成功');await load()}
async function batchDelete(){await ElMessageBox.confirm(`确定删除选中的 ${selected.value.length} 项？`,'批量删除');await Promise.all(selected.value.map(deleteOne));selected.value=[];ElMessage.success('批量删除成功');await load()}
async function saveLabels(labels:Record<string,string>){if(!selectedLabelResource.value)return;labelSaving.value=true;try{await updateKubernetesObjectLabels({cluster_id:clusterID.value,resource:resource.value,namespace:selectedLabelResource.value.namespace,name:selectedLabelResource.value.name,labels});labelDialog.value=false;ElMessage.success('标签保存成功');await load()}finally{labelSaving.value=false}}
watch(group,()=>{resource.value=group.value.resources[0].key},{immediate:true});watch(clusterID,async()=>{namespace.value='';await loadNamespaces();await load()});watch([resource,namespace,keyword],()=>{serviceType.value='';void load()});loadClusters().then(async()=>{await loadNamespaces();await load()})
</script>

<template>
  <section class="page" :class="{'workload-page':isWorkload,'network-page':isNetwork}">
    <div v-if="isWorkload" class="workload-types"><button v-for="item in stats" :key="item.key" :class="['type-card',item.tone,{active:resource===item.key}]" @click="resource=item.key"><span>{{item.label}}</span><strong>{{item.count}}</strong></button></div>
    <div v-if="isNetwork" class="network-types"><button v-for="item in networkCards" :key="item.key" :class="['network-card',{active:resource===item.key}]" @click="resource=item.key"><span>{{item.label}}</span><strong>{{item.count}}</strong></button><el-select v-model="clusterID" class="network-cluster-select" placeholder="选择集群"><el-option v-for="item in clusters" :key="item.id" :label="item.alias||item.name" :value="item.id"/></el-select></div>
    <div class="toolbar"><div class="filters"><el-select v-if="!isNetwork" v-model="clusterID" placeholder="选择集群"><el-option v-for="item in clusters" :key="item.id" :label="item.alias||item.name" :value="item.id"/></el-select><el-input v-model="keyword" :placeholder="isWorkload?'搜索工作负载名称…':isNetwork?'关键字搜索':'输入即搜索'" :clearable="!isNetwork"/><el-select v-if="isWorkload||isNetwork" v-model="namespace" placeholder="所有命名空间" clearable filterable><el-option v-for="item in namespaces" :key="item.name" :label="item.name" :value="item.name"/></el-select><el-select v-if="isNetwork&&resource==='services'" v-model="serviceType" class="service-type-select" placeholder="服务类型" clearable><el-option label="ClusterIP" value="ClusterIP"/><el-option label="NodePort" value="NodePort"/><el-option label="LoadBalancer" value="LoadBalancer"/><el-option label="ExternalName" value="ExternalName"/></el-select><el-select v-if="!isWorkload&&!isNetwork" v-model="resource"><el-option v-for="item in group.resources" :key="item.key" :label="item.label" :value="item.key"/></el-select><el-input v-if="!isWorkload&&!isNetwork&&current.namespaced" v-model="namespace" placeholder="命名空间（全部）" clearable/></div><div class="toolbar-actions"><el-button v-if="selected.length" type="danger" plain @click="batchDelete">批量删除（{{selected.length}}）</el-button><el-button class="refresh-button" :icon="Refresh" :loading="refreshing" @click="refresh">刷新</el-button><el-button class="create-button secondary" @click="blankYAML">YAML 创建</el-button><el-button v-if="isNetwork&&resource==='services'" type="primary" class="create-button" @click="openServiceCreate">创建服务</el-button><el-button v-if="isWorkload&&resource!=='pods'" type="primary" class="create-button" @click="openWorkloadCreate">表单创建</el-button></div></div>
    <AppDataGrid class="grid" :row-data="displayedRows" :column-defs="columns" :row-height="isWorkload||isNetwork ? 54 : undefined" pagination @selection-changed="selected=$event as KubernetesObject[]"/>
    <el-dialog v-model="yamlDialog" :title="`${current.label} YAML`" width="min(1080px,calc(100vw - 16px))" class="yaml-editor-dialog" align-center destroy-on-close><KubernetesYamlEditor v-model="yaml"/><template #footer><div class="yaml-dialog-footer"><el-button :loading="yamlReloading" @click="reloadYAML">重新拉取</el-button><div><el-button @click="yamlDialog=false">取消</el-button><el-button type="primary" @click="saveYAML">保存</el-button></div></div></template></el-dialog>
    <KubernetesWorkloadEditor v-model="workloadEditorDialog" :yaml="workloadEditorYaml" :saving="workloadEditorSaving" :create-mode="workloadEditorCreate" @save="saveWorkloadEdit"/>
    <KubernetesServiceEditor v-model="serviceEditorDialog" :yaml="serviceEditorYaml" :saving="serviceEditorSaving" :create-mode="serviceEditorCreate" @save="saveService"/>
    <KubernetesLabelDialog v-model="labelDialog" :title="`${selectedLabelResource?.name||''} 标签`" :labels="selectedLabelResource?.labels||{}" :saving="labelSaving" @save="saveLabels"/>
  </section>
</template>

<style scoped>
.page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;min-height:0}.toolbar,.filters,.toolbar-actions{display:flex;align-items:center;gap:8px}.toolbar{justify-content:space-between}.filters{min-width:0;flex-wrap:wrap}.filters .el-select{width:170px}.filters .el-input{width:240px}.grid{flex:1;min-height:0}.workload-types{display:grid;grid-template-columns:repeat(6,minmax(105px,132px));justify-content:start;gap:6px}.type-card{display:flex;align-items:center;gap:6px;padding:7px 9px;border:1px solid var(--line);border-radius:8px;background:#fff;color:#717784;cursor:pointer}.type-card:hover,.type-card.active{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 5%,white);color:var(--primary)}.type-card strong{margin-left:auto;font-size:17px;color:var(--text)}.type-icon{display:grid;place-items:center;width:27px;height:27px;border-radius:7px;font-weight:700;background:#edf3ff;color:#326ce5}.purple .type-icon{background:#f2efff;color:#7656d6}.cyan .type-icon{background:#eaf8fa;color:#16818d}.orange .type-icon{background:#fff5e5;color:#c57815}.pink .type-icon{background:#fff0f6;color:#be4f7d}.green .type-icon{background:#ebf8f0;color:#238d52}.create-button{min-width:96px}.create-button.secondary{border-color:var(--primary);color:var(--primary);background:#fff}.yaml :deep(textarea){font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px}.page :deep(.centered-grid-header .ag-header-cell-label){justify-content:center}.page :deep(.left-grid-header .ag-header-cell-label){justify-content:flex-start}.page :deep(.centered-grid-cell){display:flex;align-items:center;justify-content:center;text-align:center}.page :deep(.centered-grid-cell .ag-cell-wrapper),.page :deep(.centered-grid-cell .ag-cell-value){display:flex;height:100%;align-items:center;justify-content:center}.page :deep(.left-grid-cell){display:flex;align-items:center;justify-content:flex-start;overflow:hidden;text-align:left}.page :deep(.left-grid-cell .ag-cell-value){min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.page :deep(.workload-name-cell){display:flex;align-items:center;justify-content:flex-start;width:100%;height:100%;overflow:hidden;text-align:left}.page :deep(.workload-name-cell span){display:flex;min-width:0;flex-direction:column;line-height:18px}.page :deep(.workload-name-cell b),.page :deep(.workload-name-cell small){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.page :deep(.workload-name-cell small){color:#9298a5}.page :deep(.workload-labels){color:#b48800;cursor:help}.page :deep(.actions){display:flex;align-items:center;justify-content:center;gap:12px;width:100%;height:100%}.page :deep(.icon-action){display:inline-flex;width:24px;height:24px;align-items:center;justify-content:center;padding:0;border:0;border-radius:5px;background:transparent;color:#d5a100;line-height:1;cursor:pointer}.page :deep(.icon-action svg){width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.page :deep(.icon-action:hover){background:#fff8df}.page :deep(.icon-action.danger){color:#f06464}.page :deep(.icon-action.danger:hover){background:#fff0f0}@media(max-width:980px){.workload-types{grid-template-columns:repeat(3,minmax(105px,132px))}.toolbar{align-items:flex-start;flex-direction:column}.toolbar-actions{align-self:flex-end}}@media(max-width:620px){.workload-types{grid-template-columns:repeat(2,minmax(105px,132px))}.filters .el-input,.filters .el-select{width:100%}}
